package com.arena.core.publicclub;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.http.MockHttpInputMessage;
import org.springframework.core.MethodParameter;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import java.time.Instant;import java.util.HexFormat;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;
import static org.junit.jupiter.api.Assertions.*;
class PublicHostContractTest {
 static final String KEY="12345678901234567890123456789012";
 String sign(String host,String time)throws Exception{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(KEY.getBytes(),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal((host+"\n"+time).getBytes()));}
 MockHttpServletRequest request(String host,long offset)throws Exception{String time=""+(Instant.now().getEpochSecond()+offset);var r=new MockHttpServletRequest();r.addHeader("X-Arena-Public-Host",host);r.addHeader("X-Arena-Public-Time",time);r.addHeader("X-Arena-Public-Signature",sign(host,time));return r;}
 @Test void signedHostnameResolvesWithoutTrustingForwardedOrBodyTenant()throws Exception{var hosts=new PublicClubHost(KEY,"arenaops.test","https","8443");var r=request("speed.arenaops.test",0);r.addHeader("Host","evil.invalid");r.addHeader("X-Forwarded-Host","other.arenaops.test");assertEquals("speed",hosts.verifiedSlug(r));assertEquals("https://speed.arenaops.test:8443",hosts.origin("speed"));}
 @Test void missingTamperedStaleWrongDomainAndReservedHostFailClosed()throws Exception{var hosts=new PublicClubHost(KEY,"arenaops.test","https","");assertThrows(RuntimeException.class,()->hosts.verifiedSlug(new MockHttpServletRequest()));for(String h:new String[]{"speed.evil.test","speed.arenaops.test.evil","x.speed.arenaops.test","admin.arenaops.test","Speed.arenaops.test"})assertThrows(RuntimeException.class,()->hosts.verifiedSlug(request(h,0)));assertThrows(RuntimeException.class,()->hosts.verifiedSlug(request("speed.arenaops.test",-120)));assertThrows(RuntimeException.class,()->new PublicClubHost("","arenaops.test","https","").verifiedSlug(request("speed.arenaops.test",0)));var r=request("speed.arenaops.test",0);r.removeHeader("X-Arena-Public-Signature");r.addHeader("X-Arena-Public-Signature","bad");assertThrows(RuntimeException.class,()->hosts.verifiedSlug(r));}
 @Test void publicPayloadRejectsExtraTenantFieldsMalformedJsonAndLargeBodies()throws Exception{var advice=new PublicPayloadFields();var method=PublicClubController.class.getMethod("request",jakarta.servlet.http.HttpServletRequest.class,PublicClubContracts.Booking.class);var p=new MethodParameter(method,1);assertTrue(advice.supports(p,PublicClubContracts.Booking.class,MappingJackson2HttpMessageConverter.class));for(String body:new String[]{"{\"academyId\":2}","[]","{","{\"name\":\""+"a".repeat(2100)+"\"}"})assertThrows(org.springframework.http.converter.HttpMessageNotReadableException.class,()->advice.beforeBodyRead(new MockHttpInputMessage(body.getBytes()),p,PublicClubContracts.Booking.class,MappingJackson2HttpMessageConverter.class));var input=advice.beforeBodyRead(new MockHttpInputMessage("{\"name\":\"Guest\"}".getBytes()),p,PublicClubContracts.Booking.class,MappingJackson2HttpMessageConverter.class);assertEquals("{\"name\":\"Guest\"}",new String(input.getBody().readAllBytes()));}
 @Test void privateResponseDiagnosticsRedactContactDataWithoutChangingJson()throws Exception{var c=new ClubCustomerService.View(1L,"Private Guest","+919876543210","UNVERIFIED",null,null,1,null,null);var b=new PublicClubContracts.BookingPending(2L,"E1","Private Guest","+919876543210",null,null,null);for(var row:new Object[]{c,b}){assertFalse(row.toString().contains("Private Guest"));assertFalse(row.toString().contains("9876543210"));var json=new com.fasterxml.jackson.databind.ObjectMapper().valueToTree(row);assertEquals("Private Guest",json.path("name").asText());assertEquals("+919876543210",json.path("mobile").asText());}}

 @Test void signedSharedHostIsAcceptedOnlyByCheckinResolver()throws Exception{var hosts=new PublicClubHost(KEY,"arenaops.test","https","");assertNull(hosts.verifiedCheckinSlug(request("arenaops.test",0)));assertEquals("speed",hosts.verifiedCheckinSlug(request("speed.arenaops.test",0)));assertThrows(RuntimeException.class,()->hosts.verifiedSlug(request("arenaops.test",0)));assertThrows(RuntimeException.class,()->hosts.verifiedCheckinSlug(new MockHttpServletRequest()));assertThrows(RuntimeException.class,()->hosts.verifiedCheckinSlug(request("evil.invalid",0)));assertThrows(RuntimeException.class,()->hosts.verifiedCheckinSlug(request("arenaops.test",-120)));}
}
